import Distributions: logcdf, Rayleigh
import JSON

"""
	gen( x, sigma, name )

Generate fixture data and write to file.

# Arguments

* `x`: input value
* `sigma`: scale parameter
* `name::AbstractString`: output filename

# Examples

``` julia
julia> x = range( 0, stop = 50, length = 1001 );
julia> sigma = range( 1, stop = 10, length = 1001 );
julia> gen( x, sigma, \"data.json\" );
```
"""
function gen( x, sigma, name )
	z = Array{Float64}( undef, length(x) );
	for i in eachindex(x)
		z[ i ] = logcdf( Rayleigh( sigma[i] ), x[i] );
	end

	# Store data to be written to file as a collection:
	data = Dict([
		("x", x),
		("sigma", sigma),
		("expected", z)
	]);

	# Based on the script directory, create an output filepath:
	filepath = joinpath( dir, name );

	# Write the data to the output filepath as JSON:
	outfile = open( filepath, "w" );
	write( outfile, JSON.json(data) );
	write( outfile, "\n" );
	close( outfile );
end

"""
	gen_small( x, sigma, name )

Generate fixture data for small `x` in extended precision and write to file. In double precision, `x^2` underflows for small `x`, so the reference value is computed from the textbook formula `ln(1 - exp(-x^2/(2*sigma^2)))`, written with `expm1` so that it stays exact at 2048 bits.

# Arguments

* `x`: input value
* `sigma`: scale parameter
* `name::AbstractString`: output filename
"""
function gen_small( x, sigma, name )
	z = setprecision( BigFloat, 2048 ) do
		Float64.( log.( .-expm1.( .-( BigFloat.( x ) .^ 2 ) ./ ( 2 .* BigFloat.( sigma ) .^ 2 ) ) ) )
	end

	# Store data to be written to file as a collection:
	data = Dict([
		("x", x),
		("sigma", sigma),
		("expected", z)
	]);

	# Based on the script directory, create an output filepath:
	filepath = joinpath( dir, name );

	# Write the data to the output filepath as JSON:
	outfile = open( filepath, "w" );
	write( outfile, JSON.json(data) );
	write( outfile, "\n" );
	close( outfile );
end

# Get the filename:
file = @__FILE__;

# Extract the directory in which this file resides:
dir = dirname( file );

# Large scale parameter:
x = rand( 1000 ) .* 20.0;
sigma = rand( 1000 ) .* 50.0;
gen( x, sigma, "large_scale.json" );

# Medium scale parameter:
x = rand( 1000 ) .* 20.0;
sigma = rand( 1000 ) .* 20.0;
gen( x, sigma, "medium_scale.json" );

# Small scale parameter:
x = rand( 1000 ) .* 20.0;
sigma = rand( 1000 ) .* 5.0;
gen( x, sigma, "small_scale.json" );

# Small `x`:
x = exp10.( range( -300.0, stop = -2.0, length = 1000 ) );
sigma = ( rand( 1000 ) .* 10.0 ) .+ 0.1;
gen_small( x, sigma, "small_x.json" );
